sp_widget.script:
(function(data, input) {
	data.trips = [];
	if (!gs.getUserID()) { return; }
	var gr = new GlideRecord("x_travel_buddy_app_trip_request");
	gr.addQuery("u_traveler", gs.getUserID());
	gr.orderByDesc("sys_created_on");
	gr.query();
	while (gr.next()) {
		var buddyName = "";
		var buddyId = gr.getValue("u_buddy");
		if (buddyId) {
			var buddyGr = new GlideRecord("sys_user");
			if (buddyGr.get(buddyId)) {
				buddyName = buddyGr.getValue("name") || buddyGr.getValue("user_name") || "";
			}
		}
		data.trips.push({
			number: gr.getValue("number"),
			destination: gr.u_destination.getDisplayValue(),
			startDate: gr.start_time.getDisplayValue(),
			endDate: gr.end_time.getDisplayValue(),
			pkg: gr.u_destination_package.getDisplayValue(),
			travelType: gr.u_travel_type.getDisplayValue(),
			buddy: buddyName,
			weather: gr.getValue("weather"),
			state: gr.getDisplayValue("state")
		});
	}
})(data, input);
